package com.example.ancapp.data

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.withContext
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.time.LocalDate

class PatientRepository(private val context: Context) {

    private val storageFile: File
        get() = File(context.filesDir, "anc_database.json")

    private val _patients = MutableStateFlow<List<Patient>>(emptyList())
    val patients: StateFlow<List<Patient>> = _patients.asStateFlow()

    private val _visits = MutableStateFlow<List<AncVisit>>(emptyList())
    val visits: StateFlow<List<AncVisit>> = _visits.asStateFlow()

    init {
        loadData()
    }

    private fun loadData() {
        val file = storageFile
        if (!file.exists() || file.length() == 0L) {
            seedInitialData()
        } else {
            try {
                val jsonString = file.readText()
                val rootJson = JSONObject(jsonString)

                val patientsArray = rootJson.getJSONArray("patients")
                val loadedPatients = mutableListOf<Patient>()
                for (i in 0 until patientsArray.length()) {
                    val obj = patientsArray.getJSONObject(i)
                    loadedPatients.add(
                        Patient(
                            id = obj.getString("id"),
                            name = obj.getString("name"),
                            dateOfBirth = LocalDate.parse(obj.getString("dateOfBirth")),
                            estimatedDueDate = LocalDate.parse(obj.getString("estimatedDueDate"))
                        )
                    )
                }

                val visitsArray = rootJson.getJSONArray("visits")
                val loadedVisits = mutableListOf<AncVisit>()
                for (i in 0 until visitsArray.length()) {
                    val obj = visitsArray.getJSONObject(i)
                    val dangerSignsArray = obj.optJSONArray("dangerSigns")
                    val dangerSignsList = mutableListOf<String>()
                    if (dangerSignsArray != null) {
                        for (j in 0 until dangerSignsArray.length()) {
                            dangerSignsList.add(dangerSignsArray.getString(j))
                        }
                    } else {
                        dangerSignsList.add(DangerSigns.NONE)
                    }

                    val hemoglobinVal = if (obj.has("hemoglobin") && !obj.isNull("hemoglobin")) {
                        obj.getDouble("hemoglobin")
                    } else null

                    loadedVisits.add(
                        AncVisit(
                            id = obj.getString("id"),
                            patientId = obj.getString("patientId"),
                            visitDate = LocalDate.parse(obj.getString("visitDate")),
                            gestationalAgeWeeks = obj.getInt("gestationalAgeWeeks"),
                            weightKg = obj.getDouble("weightKg"),
                            systolicBp = obj.getInt("systolicBp"),
                            diastolicBp = obj.getInt("diastolicBp"),
                            hemoglobin = hemoglobinVal,
                            dangerSigns = dangerSignsList,
                            notes = obj.optString("notes", "")
                        )
                    )
                }

                _patients.value = loadedPatients
                _visits.value = loadedVisits
            } catch (e: Exception) {
                e.printStackTrace()
                seedInitialData()
            }
        }
    }

    private fun seedInitialData() {
        val emily = Patient(
            id = "patient-emily-carter",
            name = "Emily Carter",
            dateOfBirth = LocalDate.parse("1996-04-12"),
            estimatedDueDate = LocalDate.parse("2026-12-05")
        )
        val sarah = Patient(
            id = "patient-sarah-mitchell",
            name = "Sarah Mitchell",
            dateOfBirth = LocalDate.parse("1990-11-02"),
            estimatedDueDate = LocalDate.parse("2027-01-20")
        )
        val grace = Patient(
            id = "patient-grace-thompson",
            name = "Grace Thompson",
            dateOfBirth = LocalDate.parse("2001-07-30"),
            estimatedDueDate = LocalDate.parse("2026-10-15")
        )

        val emilyVisit = AncVisit(
            id = "visit-emily-1",
            patientId = emily.id,
            visitDate = LocalDate.parse("2026-08-10"),
            gestationalAgeWeeks = 23,
            weightKg = 68.5,
            systolicBp = 118,
            diastolicBp = 76,
            hemoglobin = 11.8,
            dangerSigns = listOf(DangerSigns.NONE),
            notes = "Routine initial ANC visit. Fetal movement noted."
        )

        val sarahVisit = AncVisit(
            id = "visit-sarah-1",
            patientId = sarah.id,
            visitDate = LocalDate.parse("2026-08-12"),
            gestationalAgeWeeks = 17,
            weightKg = 61.2,
            systolicBp = 110,
            diastolicBp = 70,
            hemoglobin = 12.4,
            dangerSigns = listOf(DangerSigns.NONE),
            notes = "Initial ANC evaluation. Blood pressure and vitals stable."
        )

        val graceVisit = AncVisit(
            id = "visit-grace-1",
            patientId = grace.id,
            visitDate = LocalDate.parse("2026-08-05"),
            gestationalAgeWeeks = 30,
            weightKg = 72.0,
            systolicBp = 128,
            diastolicBp = 84,
            hemoglobin = 10.2,
            dangerSigns = listOf(DangerSigns.NONE),
            notes = "Routine ANC checkup. Mild anemia (Hb 10.2), iron supplementation prescribed."
        )

        val seededPatients = listOf(emily, sarah, grace)
        val seededVisits = listOf(emilyVisit, sarahVisit, graceVisit)

        _patients.value = seededPatients
        _visits.value = seededVisits
        persistData(seededPatients, seededVisits)
    }

    private fun persistData(patients: List<Patient>, visits: List<AncVisit>) {
        try {
            val root = JSONObject()

            val patientsArray = JSONArray()
            for (p in patients) {
                val pObj = JSONObject().apply {
                    put("id", p.id)
                    put("name", p.name)
                    put("dateOfBirth", p.dateOfBirth.toString())
                    put("estimatedDueDate", p.estimatedDueDate.toString())
                }
                patientsArray.put(pObj)
            }
            root.put("patients", patientsArray)

            val visitsArray = JSONArray()
            for (v in visits) {
                val vObj = JSONObject().apply {
                    put("id", v.id)
                    put("patientId", v.patientId)
                    put("visitDate", v.visitDate.toString())
                    put("gestationalAgeWeeks", v.gestationalAgeWeeks)
                    put("weightKg", v.weightKg)
                    put("systolicBp", v.systolicBp)
                    put("diastolicBp", v.diastolicBp)
                    if (v.hemoglobin != null) {
                        put("hemoglobin", v.hemoglobin)
                    } else {
                        put("hemoglobin", JSONObject.NULL)
                    }
                    val dsArray = JSONArray()
                    v.dangerSigns.forEach { dsArray.put(it) }
                    put("dangerSigns", dsArray)
                    put("notes", v.notes)
                }
                visitsArray.put(vObj)
            }
            root.put("visits", visitsArray)

            // Write atomically to temp file, then rename
            val tempFile = File(context.filesDir, "anc_database.json.tmp")
            tempFile.writeText(root.toString(2))
            if (tempFile.renameTo(storageFile)) {
                // renamed successfully
            } else {
                storageFile.writeText(root.toString(2))
                tempFile.delete()
            }
        } catch (e: Exception) {
            e.printStackTrace()
        }
    }

    suspend fun addVisit(visit: AncVisit) = withContext(Dispatchers.IO) {
        val updated = _visits.value + visit
        _visits.value = updated
        persistData(_patients.value, updated)
    }

    suspend fun addPatient(patient: Patient) = withContext(Dispatchers.IO) {
        val updated = _patients.value + patient
        _patients.value = updated
        persistData(updated, _visits.value)
    }

    fun getPatient(id: String): Patient? {
        return _patients.value.find { it.id == id }
    }

    fun getVisitsForPatient(patientId: String): List<AncVisit> {
        return _visits.value.filter { it.patientId == patientId }
            .sortedByDescending { it.visitDate }
    }
}

package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import com.example.ancapp.data.AncVisit
import com.example.ancapp.data.DangerSigns
import com.example.ancapp.data.Patient
import com.example.ancapp.data.PatientRepository
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch
import java.time.LocalDate
import java.time.format.DateTimeFormatter

sealed interface Screen {
    data object Register : Screen
    data class PatientDetail(val patientId: String) : Screen
    data class RecordVisit(val patientId: String) : Screen
}

data class VisitFormState(
    val visitDate: LocalDate = LocalDate.now(),
    val gestationalAgeWeeks: String = "",
    val weightKg: String = "",
    val systolicBp: String = "",
    val diastolicBp: String = "",
    val hemoglobin: String = "",
    val dangerSigns: Set<String> = setOf(DangerSigns.NONE),
    val notes: String = "",
    val errors: Map<String, String> = emptyMap(),
    val isSaving: Boolean = false
)

class AncViewModel(application: Application) : AndroidViewModel(application) {

    private val repository = PatientRepository(application)

    private val _currentScreen = MutableStateFlow<Screen>(Screen.Register)
    val currentScreen: StateFlow<Screen> = _currentScreen.asStateFlow()

    val patients: StateFlow<List<Patient>> = repository.patients
        .combine(MutableStateFlow(Unit)) { list, _ ->
            // Sorted by due date (soonest first)
            list.sortedBy { it.estimatedDueDate }
        }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    val visits: StateFlow<List<AncVisit>> = repository.visits

    private val _formState = MutableStateFlow(VisitFormState())
    val formState: StateFlow<VisitFormState> = _formState.asStateFlow()

    fun navigateToRegister() {
        _currentScreen.value = Screen.Register
    }

    fun navigateToPatientDetail(patientId: String) {
        _currentScreen.value = Screen.PatientDetail(patientId)
    }

    fun navigateToRecordVisit(patientId: String) {
        val patient = repository.getPatient(patientId)
        val today = LocalDate.now()
        val calculatedWeeks = patient?.calculateGestationalAgeWeeks(today)?.toString() ?: ""

        _formState.value = VisitFormState(
            visitDate = today,
            gestationalAgeWeeks = calculatedWeeks,
            weightKg = "",
            systolicBp = "",
            diastolicBp = "",
            hemoglobin = "",
            dangerSigns = setOf(DangerSigns.NONE),
            notes = "",
            errors = emptyMap()
        )
        _currentScreen.value = Screen.RecordVisit(patientId)
    }

    fun updateVisitDate(date: LocalDate, patientId: String) {
        val patient = repository.getPatient(patientId)
        val calculatedWeeks = patient?.calculateGestationalAgeWeeks(date)?.toString() ?: _formState.value.gestationalAgeWeeks
        _formState.value = _formState.value.copy(
            visitDate = date,
            gestationalAgeWeeks = calculatedWeeks,
            errors = _formState.value.errors - "visitDate"
        )
    }

    fun updateGestationalAge(weeks: String) {
        _formState.value = _formState.value.copy(
            gestationalAgeWeeks = weeks,
            errors = _formState.value.errors - "gestationalAge"
        )
    }

    fun updateWeight(weight: String) {
        _formState.value = _formState.value.copy(
            weightKg = weight,
            errors = _formState.value.errors - "weight"
        )
    }

    fun updateSystolicBp(systolic: String) {
        _formState.value = _formState.value.copy(
            systolicBp = systolic,
            errors = _formState.value.errors - "systolicBp"
        )
    }

    fun updateDiastolicBp(diastolic: String) {
        _formState.value = _formState.value.copy(
            diastolicBp = diastolic,
            errors = _formState.value.errors - "diastolicBp"
        )
    }

    fun updateHemoglobin(hb: String) {
        _formState.value = _formState.value.copy(
            hemoglobin = hb,
            errors = _formState.value.errors - "hemoglobin"
        )
    }

    fun updateNotes(notes: String) {
        _formState.value = _formState.value.copy(notes = notes)
    }

    fun toggleDangerSign(sign: String) {
        val currentSigns = _formState.value.dangerSigns.toMutableSet()
        if (sign == DangerSigns.NONE) {
            currentSigns.clear()
            currentSigns.add(DangerSigns.NONE)
        } else {
            currentSigns.remove(DangerSigns.NONE)
            if (currentSigns.contains(sign)) {
                currentSigns.remove(sign)
            } else {
                currentSigns.add(sign)
            }
            if (currentSigns.isEmpty()) {
                currentSigns.add(DangerSigns.NONE)
            }
        }
        _formState.value = _formState.value.copy(
            dangerSigns = currentSigns,
            errors = _formState.value.errors - "dangerSigns"
        )
    }

    fun saveVisit(patientId: String, onSuccess: () -> Unit) {
        val state = _formState.value
        val errors = mutableMapOf<String, String>()

        val gestationalAge = state.gestationalAgeWeeks.trim().toIntOrNull()
        if (gestationalAge == null || gestationalAge < 0 || gestationalAge > 50) {
            errors["gestationalAge"] = "Enter valid weeks (0-50)"
        }

        val weight = state.weightKg.trim().toDoubleOrNull()
        if (weight == null || weight <= 20 || weight > 300) {
            errors["weight"] = "Enter valid weight in kg (e.g. 65.0)"
        }

        val systolic = state.systolicBp.trim().toIntOrNull()
        if (systolic == null || systolic <= 40 || systolic > 300) {
            errors["systolicBp"] = "Enter valid systolic BP (e.g. 120)"
        }

        val diastolic = state.diastolicBp.trim().toIntOrNull()
        if (diastolic == null || diastolic <= 20 || diastolic > 200) {
            errors["diastolicBp"] = "Enter valid diastolic BP (e.g. 80)"
        }

        var hb: Double? = null
        if (state.hemoglobin.isNotBlank()) {
            hb = state.hemoglobin.trim().toDoubleOrNull()
            if (hb == null || hb <= 2.0 || hb > 30.0) {
                errors["hemoglobin"] = "Enter valid Hb (e.g. 11.5)"
            }
        }

        if (state.dangerSigns.isEmpty()) {
            errors["dangerSigns"] = "Select at least one danger sign or 'None'"
        }

        if (errors.isNotEmpty()) {
            _formState.value = state.copy(errors = errors)
            return
        }

        viewModelScope.launch {
            _formState.value = state.copy(isSaving = true)
            val newVisit = AncVisit(
                patientId = patientId,
                visitDate = state.visitDate,
                gestationalAgeWeeks = gestationalAge!!,
                weightKg = weight!!,
                systolicBp = systolic!!,
                diastolicBp = diastolic!!,
                hemoglobin = hb,
                dangerSigns = state.dangerSigns.toList(),
                notes = state.notes.trim()
            )
            repository.addVisit(newVisit)
            _formState.value = VisitFormState()
            _currentScreen.value = Screen.PatientDetail(patientId)
            onSuccess()
        }
    }

    fun getPatient(id: String): Patient? = repository.getPatient(id)

    fun getVisitsForPatient(patientId: String): List<AncVisit> =
        repository.getVisitsForPatient(patientId)
}

