@Composable
fun PatientDetailScreen(
    patient: Patient?,
    visits: List<AncVisit>,
    onBackClick: () -> Unit,
    onRecordVisitClick: () -> Unit
) {
    if (patient == null) {
        Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
            Text("Patient not found")
        }
        return
    }

    val today = LocalDate.now()
    val age = patient.calculateAge(today)
    val gestationalWeeks = patient.calculateGestationalAgeWeeks(today)
    val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Text(
                        text = patient.name,
                        fontWeight = FontWeight.Bold,
                        fontSize = 18.sp
                    )
                },
                navigationIcon = {
                    IconButton(
                        onClick = onBackClick,
                        modifier = Modifier.testTag("detail_back_button")
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back to Register"
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.surface,
                    titleContentColor = MaterialTheme.colorScheme.onSurface
                )
            )
        },
        floatingActionButton = {
            ExtendedFloatingActionButton(
                onClick = onRecordVisitClick,
                icon = { Icon(Icons.Default.Add, contentDescription = null) },
                text = { Text("Record ANC Visit", fontWeight = FontWeight.SemiBold) },
                containerColor = MaterialTheme.colorScheme.primary,
