@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun RecordVisitScreen(
    patient: Patient?,
    formState: VisitFormState,
    onVisitDateChange: (LocalDate) -> Unit,
    onGestationalAgeChange: (String) -> Unit,
    onWeightChange: (String) -> Unit,
    onSystolicBpChange: (String) -> Unit,
    onDiastolicBpChange: (String) -> Unit,
    onHemoglobinChange: (String) -> Unit,
    onToggleDangerSign: (String) -> Unit,
    onNotesChange: (String) -> Unit,
    onSaveClick: () -> Unit,
    onBackClick: () -> Unit
) {
    val context = LocalContext.current
    val scrollState = rememberScrollState()
    val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

    Scaffold(
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text(
                            text = "Record ANC Visit",
                            fontWeight = FontWeight.Bold,
                            fontSize = 18.sp
                        )
                        if (patient != null) {
                            Text(
                                text = "Patient: ${patient.name}",
                                style = MaterialTheme.typography.bodySmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant
                            )
                        }
                    }
                },
                navigationIcon = {
                    IconButton(
                        onClick = onBackClick,
                        modifier = Modifier.testTag("form_back_button")
                    ) {
                        Icon(
                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back"
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.surface,
                    titleContentColor = MaterialTheme.colorScheme.onSurface
                )
            )
        },
        containerColor = MaterialTheme.colorScheme.background
    ) { innerPadding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .verticalScroll(scrollState)
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            // Visit Date Picker Field
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surface
                ),
                shape = RoundedCornerShape(12.dp)
            ) {
                Column(modifier = Modifier.padding(16.dp)) {
                    Text(
                        text = "Visit Date",
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.SemiBold,
                        color = MaterialTheme.colorScheme.onSurface
                    )
                    Spacer(modifier = Modifier.height(8.dp))
                    OutlinedButton(
                        onClick = {
                            val currentDate = formState.visitDate
                            DatePickerDialog(
                                context,
                                { _, year, month, dayOfMonth ->
                                    val selectedDate = LocalDate.of(year, month + 1, dayOfMonth)
                                    onVisitDateChange(selectedDate)
                                },
                                currentDate.year,
                                currentDate.monthValue - 1,
                                currentDate.dayOfMonth
                            ).show()
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("date_picker_button"),
                        shape = RoundedCornerShape(8.dp)
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth(),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Text(
                                text = formState.visitDate.format(dateFormatter),
                                style = MaterialTheme.typography.bodyLarge,
                                fontWeight = FontWeight.SemiBold
                            )
                            Icon(
                                imageVector = Icons.Default.CalendarMonth,
                                contentDescription = "Select Date"
                            )
                        }
                    }
                }
            }

            // Gestational Age & Weight Section
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surface
                ),
                shape = RoundedCornerShape(12.dp)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text(
                        text = "Gestational Age & Weight",
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.SemiBold
                    )

                    OutlinedTextField(
                        value = formState.gestationalAgeWeeks,
                        onValueChange = onGestationalAgeChange,
                        label = { Text("Gestational Age (weeks)") },
                        placeholder = { Text("e.g. 28") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        isError = formState.errors.containsKey("gestationalAge"),
                        supportingText = {
                            formState.errors["gestationalAge"]?.let {
                                Text(it, color = MaterialTheme.colorScheme.error)
                            } ?: Text("Estimated weeks of pregnancy")
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("input_gestational_age"),
                        singleLine = true
                    )

                    OutlinedTextField(
                        value = formState.weightKg,
                        onValueChange = onWeightChange,
                        label = { Text("Weight (kg)") },
                        placeholder = { Text("e.g. 68.5") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                        isError = formState.errors.containsKey("weight"),
                        supportingText = {
                            formState.errors["weight"]?.let {
                                Text(it, color = MaterialTheme.colorScheme.error)
                            }
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("input_weight"),
                        singleLine = true
                    )
                }
            }

            // Blood Pressure & Hemoglobin Section
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surface
                ),
                shape = RoundedCornerShape(12.dp)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text(
                        text = "Vitals & Lab",
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.SemiBold
                    )

                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.spacedBy(12.dp)
                    ) {
                        OutlinedTextField(
                            value = formState.systolicBp,
                            onValueChange = onSystolicBpChange,
                            label = { Text("Systolic (mmHg)") },
                            placeholder = { Text("120") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            isError = formState.errors.containsKey("systolicBp"),
                            supportingText = {
                                formState.errors["systolicBp"]?.let {
                                    Text(it, color = MaterialTheme.colorScheme.error)
                                }
                            },
                            modifier = Modifier
                                .weight(1f)
                                .testTag("input_systolic_bp"),
                            singleLine = true
                        )

                        OutlinedTextField(
                            value = formState.diastolicBp,
                            onValueChange = onDiastolicBpChange,
                            label = { Text("Diastolic (mmHg)") },
                            placeholder = { Text("80") },
                            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                            isError = formState.errors.containsKey("diastolicBp"),
                            supportingText = {
                                formState.errors["diastolicBp"]?.let {
                                    Text(it, color = MaterialTheme.colorScheme.error)
                                }
                            },
                            modifier = Modifier
                                .weight(1f)
                                .testTag("input_diastolic_bp"),
                            singleLine = true
                        )
                    }

                    OutlinedTextField(
                        value = formState.hemoglobin,
                        onValueChange = onHemoglobinChange,
                        label = { Text("Hemoglobin (g/dL) - Optional") },
                        placeholder = { Text("e.g. 11.8") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                        isError = formState.errors.containsKey("hemoglobin"),
                        supportingText = {
                            formState.errors["hemoglobin"]?.let {
                                Text(it, color = MaterialTheme.colorScheme.error)
                            } ?: Text("Leave blank if Hb was not tested this visit")
                        },
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("input_hemoglobin"),
                        singleLine = true
                    )
                }
            }

            // Danger Signs Section
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surface
                ),
                shape = RoundedCornerShape(12.dp)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(6.dp)
                    ) {
                        Icon(
                            imageVector = Icons.Default.Warning,
                            contentDescription = null,
                            tint = MaterialTheme.colorScheme.error,
                            modifier = Modifier.size(18.dp)
                        )
                        Text(
                            text = "Danger Signs",
                            style = MaterialTheme.typography.labelMedium,
                            fontWeight = FontWeight.SemiBold
                        )
                    }

                    Text(
                        text = "Select all observed danger signs (or 'None' if normal):",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )

                    // Danger signs chips
                    FlowRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("danger_signs_container"),
                        horizontalArrangement = Arrangement.spacedBy(8.dp),
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        DangerSigns.ALL.forEach { sign ->
                            val isSelected = formState.dangerSigns.contains(sign)
                            val isDanger = sign != DangerSigns.NONE

                            FilterChip(
                                selected = isSelected,
                                onClick = { onToggleDangerSign(sign) },
                                label = { Text(sign) },
                                leadingIcon = if (isSelected) {
                                    {
                                        Icon(
                                            imageVector = Icons.Default.Check,
                                            contentDescription = null,
                                            modifier = Modifier.size(16.dp)
                                        )
                                    }
                                } else null,
                                colors = if (isDanger && isSelected) {
                                    FilterChipDefaults.filterChipColors(
                                        selectedContainerColor = DangerRedContainer,
                                        selectedLabelColor = DangerOnRedContainer,
                                        selectedLeadingIconColor = DangerOnRedContainer
                                    )
                                } else {
                                    FilterChipDefaults.filterChipColors()
                                },
                                modifier = Modifier.testTag("chip_danger_sign_$sign")
                            )
                        }
                    }

                    if (formState.errors.containsKey("dangerSigns")) {
                        Text(
                            text = formState.errors["dangerSigns"] ?: "",
                            color = MaterialTheme.colorScheme.error,
                            style = MaterialTheme.typography.bodySmall
                        )
                    }
                }
            }

            // Free-Text Notes Section
            Card(
                colors = CardDefaults.cardColors(
                    containerColor = MaterialTheme.colorScheme.surface
                ),
                shape = RoundedCornerShape(12.dp)
            ) {
                Column(
                    modifier = Modifier.padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp)
                ) {
                    Text(
                        text = "Clinical Notes",
                        style = MaterialTheme.typography.labelMedium,
                        fontWeight = FontWeight.SemiBold
                    )

                    OutlinedTextField(
                        value = formState.notes,
                        onValueChange = onNotesChange,
                        label = { Text("Free-text notes") },
                        placeholder = { Text("Clinical observations, treatments, referrals, instructions...") },
                        minLines = 3,
                        maxLines = 6,
                        modifier = Modifier
                            .fillMaxWidth()
                            .testTag("input_notes")
                    )
                }
            }

            // Action Buttons
            Button(
                onClick = onSaveClick,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(52.dp)
                    .testTag("save_visit_button"),
                shape = RoundedCornerShape(12.dp),
                enabled = !formState.isSaving
            ) {
                if (formState.isSaving) {
                    CircularProgressIndicator(
                        modifier = Modifier.size(24.dp),
                        color = MaterialTheme.colorScheme.onPrimary,
                        strokeWidth = 2.dp
                    )
                } else {
                    Text(
                        text = "Save ANC Visit",
                        style = MaterialTheme.typography.bodyLarge,
                        fontWeight = FontWeight.Bold
                    )
                }
            }

            OutlinedButton(
                onClick = onBackClick,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(48.dp)
                    .testTag("cancel_button"),
                shape = RoundedCornerShape(12.dp)
            ) {
                Text("Cancel")
            }

            Spacer(modifier = Modifier.height(16.dp))
        }
    }
}

